<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,reactive,watch} from 'vue';
import type {PcApi} from '../api';
import type {AnalyticsDrillFilters} from '../../../../packages/contracts/src/analytics';
import {AnalyticsController,createAnalyticsState,analyticsBusy,quantityLabel,coverageLabel,beijingTime,barWidth,trendPoints,periodRangeLabel,drillPeriodLabel,periodOrderNotice} from '../../../../packages/analytics-client/src';
const props=defineProps<{api:Pick<PcApi,'get'|'post'>;admin?:boolean;locked?:boolean}>();
const emit=defineEmits<{(e:'busy-changed',busy:boolean):void;(e:'failure',error:unknown):void;(e:'openOrder',orderId:string):void}>();
const state=reactive(createAnalyticsState()),controller=new AnalyticsController(path=>props.api.get(path),(path,body)=>props.api.post(path,body),state,e=>emit('failure',e));
const busy=computed(()=>analyticsBusy(state)),locked=computed(()=>busy.value||!!props.locked),snapshot=computed(()=>state.snapshot),trend=computed(()=>state.trend==='confirmation'?snapshot.value?.charts.confirmationTrend||[]:snapshot.value?.charts.demandTrend||[]),points=computed(()=>trendPoints(trend.value,state.trend==='confirmation'));
const plotWidth=computed(()=>Math.max(660,trend.value.length*230)),selectedPeriod=computed(()=>drillPeriodLabel(snapshot.value,state.selection));
const segments=computed(()=>{const result:string[]=[];let current:string[]=[];for(const point of points.value){if(point.value===null){if(current.length)result.push(current.join(' '));current=[];}else current.push(point.x+','+point.y);}if(current.length)result.push(current.join(' '));return result;});
const maxOrders=computed(()=>Math.max(1,...(snapshot.value?.charts.frequency||[]).map(r=>r.orders))),maxQuantity=computed(()=>Math.max(1,...(snapshot.value?.charts.quantity||[]).flatMap(r=>[Number(r.demandQuantity),Number(r.confirmedQuantity)||0]))),maxRanking=computed(()=>Math.max(1,...(snapshot.value?.charts.ranking||[]).map(r=>Number(r.demandQuantity)))),maxShortage=computed(()=>Math.max(1,...(snapshot.value?.charts.shortage||[]).map(r=>(Number(r.confirmedQuantity)||0)+(Number(r.missingQuantity)||0))));
const changed=computed(()=>{const f=snapshot.value?.filters;if(!f)return false;return ['receivedFrom','receivedTo','hospitalId','name','spec','groupBy'].some(k=>(state.form[k as keyof typeof state.form]||'')!==(f[k as keyof typeof f]||''));});
const pages=computed(()=>state.drill?Math.max(1,Math.ceil(state.drill.total/state.drill.pageSize)):1);
watch(busy,value=>emit('busy-changed',value),{immediate:true,flush:'sync'});
function drill(filter:AnalyticsDrillFilters){if(!locked.value)void controller.drill(filter);}
function openOrder(id:string){if(!locked.value&&!controller.expire())emit('openOrder',id);}
async function refresh(){if(locked.value)return;await controller.query();}
let expiryTimer:ReturnType<typeof setInterval>|undefined;
onMounted(()=>{void controller.bootstrap();expiryTimer=setInterval(()=>controller.expire(),1000);});
onBeforeUnmount(()=>{clearInterval(expiryTimer);controller.dispose();emit('busy-changed',false);});
defineExpose({refresh,canLeave:()=>!busy.value});
</script>
<template>
 <section class="hospital-analytics">
  <div class="heading"><div><p class="eyebrow">需求与最终确认结果</p><h2>医院数据分析</h2><p class="muted">{{admin?'全量业务只读':'本人订单及当前负责医院的历史'}} · 确认量不代表实际发货，数量单位 kg。</p></div></div>
  <form class="filters" @submit.prevent="refresh"><label>接收日期自<input v-model="state.form.receivedFrom" type="date" required :disabled="locked"></label><label>至（含当天）<input v-model="state.form.receivedTo" type="date" required :disabled="locked"></label><label>医院<select v-model="state.form.hospitalId" :disabled="locked"><option :value="undefined">权限内全部医院</option><option v-for="h in state.hospitals" :key="h.id" :value="h.id">{{h.name}}</option></select></label><label>药品<input v-model="state.form.name" placeholder="药品名称" maxlength="100" :disabled="locked"></label><label>规格<input v-model="state.form.spec" placeholder="规格" maxlength="200" :disabled="locked"></label><label>趋势分组<select v-model="state.form.groupBy" :disabled="locked"><option value="month">自然月</option><option value="week">自然周 · 周一开始</option></select></label><button class="primary" :disabled="locked">查询 / 整组刷新</button></form>
  <p v-if="state.hospitalError" class="error">医院选项读取失败：{{state.hospitalError}} <button :disabled="locked" @click="controller.hospitals()">重新读取</button></p>
  <p v-if="changed" class="notice">筛选已修改，请查询后更新；下方仍是上次查询结果。</p><p v-if="state.error" class="error" role="alert">{{state.error}} <button :disabled="locked" @click="refresh">重新查询</button></p><p v-if="state.loading" class="empty" role="status">正在生成分析快照…</p>
  <template v-if="snapshot">
   <div class="meta"><strong>{{snapshot.filters.receivedFrom}} — {{snapshot.filters.receivedTo}}</strong><span>数据截至 {{beijingTime(snapshot.asOf)}} · {{beijingTime(snapshot.expiresAt)}} 到期</span><small>查询 {{snapshot.snapshotId}} · {{snapshot.filters.hospitalId?state.hospitals.find(h=>h.id===snapshot?.filters.hospitalId)?.name||'所选医院':'全部有权医院'}}{{snapshot.filters.name?' · 药品 '+snapshot.filters.name:''}}{{snapshot.filters.spec?' · 规格 '+snapshot.filters.spec:''}}</small></div>
   <div class="summary"><div><small>同接收批次 · 要货次数</small><strong>{{snapshot.summary.orders}} <em>单</em></strong></div><div><small>采购需求（包含缺货）</small><strong>{{snapshot.summary.demandQuantity}} <em>kg</em></strong></div><div><small>确认可供货</small><strong class="result">{{quantityLabel(snapshot.summary.confirmedQuantity,snapshot.summary.coverage,'confirmed')}}</strong></div></div>
   <p class="coverage">{{coverageLabel(snapshot.summary.coverage)}}<span v-if="snapshot.summary.confirmedAmount!==null"> 整单最终确认金额合计 ¥ {{snapshot.summary.confirmedAmount}}。</span></p>
   <p class="legend"><span><i class="demand"></i>采购需求</span><span><i class="confirmed"></i>确认可供货</span><span><i class="missing"></i>明确缺货</span><span>点击图形核对订单；未知值保留为空。</span></p>
   <p v-if="!snapshot.summary.orders" class="notice">当前接收批次暂无正式统计订单。下方确认日期趋势另按实际确认日期选单。</p>
   <div class="charts">
    <section class="chart"><small>01 / FREQUENCY</small><h3>医院要货次数</h3><p>实际接收批次，每张采购单只计一次。</p><div class="bars"><button v-for="r in snapshot.charts.frequency" :key="r.hospitalId" class="chart-row" :disabled="locked" @click="drill({chart:'frequency',hospitalId:r.hospitalId})"><span class="row-head"><strong>{{r.hospitalName}}</strong><span>{{r.orders}} 单</span></span><span class="track"><i class="demand" :style="{width:barWidth(r.orders,maxOrders)+'%'}"></i></span></button><span v-if="!snapshot.charts.frequency.length" class="empty">无匹配订单</span></div></section>
    <section class="chart"><small>02 / QUANTITY</small><h3>需求与确认数量</h3><p>同一接收批次，展示截至查询时的最终结果。</p><div class="bars"><button v-for="r in snapshot.charts.quantity" :key="r.hospitalId" class="chart-row" :disabled="locked" @click="drill({chart:'quantity',hospitalId:r.hospitalId})"><span class="row-head"><strong>{{r.hospitalName}}</strong><span>需求 {{r.demandQuantity}} kg</span></span><span class="track"><i class="demand" :style="{width:barWidth(r.demandQuantity,maxQuantity)+'%'}"></i></span><span class="track"><i class="confirmed" :style="{width:barWidth(r.confirmedQuantity,maxQuantity)+'%'}"></i></span><span class="caption">确认 {{quantityLabel(r.confirmedQuantity,r.coverage,'confirmed')}} · 待确认 {{r.coverage.pendingOrders}} 单</span></button><span v-if="!snapshot.charts.quantity.length" class="empty">无匹配订单</span></div></section>
    <section class="chart trend"><div class="trend-heading"><div><small>03 / TREND</small><h3>{{state.trend==='demand'?'按接收日期的需求趋势':'按实际确认日期的确认趋势'}}</h3></div><div class="switch"><button :class="{active:state.trend==='demand'}" :disabled="locked" @click="state.trend='demand'">接收日期 · 需求</button><button :class="{active:state.trend==='confirmation'}" :disabled="locked" @click="state.trend='confirmation'">确认日期 · 结果</button></div></div><p>北京时间{{snapshot.filters.groupBy==='month'?'自然月':'自然周（周一开始）'}}；两种日期视图分别选单，不可相加。分组标签显示完整自然期间，数量仅计入本次日期筛选中的订单。</p>
     <div v-if="points.length" class="trend-scroll"><svg :viewBox="'0 0 '+plotWidth+' 235'" :style="{minWidth:plotWidth+'px'}" role="img" :aria-label="state.trend==='demand'?'接收日期需求趋势，单位kg':'实际确认日期确认趋势，单位kg'"><line x1="40" y1="180" :x2="plotWidth-30" y2="180" stroke="#d8e0e8"/><text x="10" y="30">kg</text><text x="24" y="184">0</text><polyline v-for="(s,i) in segments" :key="i" :points="s" fill="none" :stroke="state.trend==='demand'?'#3c708c':'#3b8b79'" stroke-width="2.5"/><g v-for="p in points" :key="p.period" role="button" tabindex="0" :aria-label="p.label+'，'+(p.value===null?'未知':p.value+' kg')+(p.notice?'，'+p.notice:'')+'，核对订单'" @click="drill({chart:state.trend==='demand'?'demandTrend':'confirmationTrend',period:p.period})" @keydown.enter.prevent="drill({chart:state.trend==='demand'?'demandTrend':'confirmationTrend',period:p.period})"><title>{{p.label}} · {{p.value===null?'未知':p.value+' kg'}}{{p.notice?' · '+p.notice:''}}</title><rect :x="p.x-18" y="20" width="36" height="175" fill="transparent"/><circle v-if="p.value!==null" :cx="p.x" :cy="p.y" r="5" :fill="state.trend==='demand'?'#3c708c':'#3b8b79'"/><text :x="p.x" :y="p.value===null?160:p.y-12" text-anchor="middle">{{p.value===null?'未知':p.value}}</text><text :x="p.x" y="202" text-anchor="middle">{{p.label.split(' 至 ')[0]}}<tspan :x="p.x" dy="15">至 {{p.label.split(' 至 ')[1]}}</tspan></text></g></svg></div><p v-else class="empty">此日期口径暂无有依据的数据。</p>
     <div class="period-buttons"><button v-for="r in trend" :key="r.period" :disabled="locked" @click="drill({chart:state.trend==='demand'?'demandTrend':'confirmationTrend',period:r.period})">{{periodRangeLabel(r)}} · {{state.trend==='demand'?r.demandQuantity+' kg':quantityLabel(r.confirmedQuantity,r.coverage,'confirmed')}}{{periodOrderNotice(r)?' · '+periodOrderNotice(r):''}} ›</button></div><p class="caption">实际确认日期趋势：{{snapshot.confirmationTrendCoverage.orders}} 单；确认数量已知 {{snapshot.confirmationTrendCoverage.knownQuantityLines}} 行 / 未知 {{snapshot.confirmationTrendCoverage.unknownQuantityLines}} 行。接收批次另有 {{snapshot.confirmationTrendCoverage.unknownDateOrders}} 单实际确认日期未知，未分配到确认趋势。</p>
    </section>
    <section class="chart"><small>04 / MEDICINES</small><h3>药品规格需求排名</h3><p>按完整采购需求排序，同名不同规格分别统计。</p><div class="bars"><button v-for="(r,i) in snapshot.charts.ranking" :key="JSON.stringify([r.name,r.spec])" class="chart-row" :disabled="locked" @click="drill({chart:'ranking',name:r.name,spec:r.spec})"><span class="row-head"><strong>{{i+1}}. {{r.name}} · {{r.spec||'未填规格'}}</strong><span>{{r.demandQuantity}} kg</span></span><span class="track"><i class="demand" :style="{width:barWidth(r.demandQuantity,maxRanking)+'%'}"></i></span></button><span v-if="!snapshot.charts.ranking.length" class="empty">无匹配药品</span></div></section>
    <section class="chart"><small>05 / CONFIRMED RESULTS</small><h3>最终确认中的缺货情况</h3><p>只汇总有依据的结果，待确认与未知不推定为缺货。</p><div class="bars"><button v-for="r in snapshot.charts.shortage" :key="r.hospitalId" class="chart-row" :disabled="locked" @click="drill({chart:'shortage',hospitalId:r.hospitalId})"><span class="row-head"><strong>{{r.hospitalName}}</strong></span><span class="track stacked"><i class="confirmed" :style="{width:barWidth(r.confirmedQuantity,maxShortage)+'%'}"></i><i class="missing" :style="{width:barWidth(r.missingQuantity,maxShortage)+'%'}"></i></span><span class="caption">可供 {{quantityLabel(r.confirmedQuantity,r.coverage,'confirmed')}}<br>缺货 {{quantityLabel(r.missingQuantity,r.coverage,'missing')}}</span><span class="caption">{{coverageLabel(r.coverage)}}</span></button><span v-if="!snapshot.charts.shortage.length" class="empty">无匹配结果</span></div></section>
   </div>
   <section v-if="state.selection" class="drill"><div class="trend-heading"><h3>对应订单核对{{selectedPeriod?' · '+selectedPeriod:''}}</h3><button :disabled="locked" @click="controller.closeDrill()">收起</button></div><p>与本次图表使用同一查询快照。需求采用最新冻结或已核实来源，最终结果采用独立确认来源。</p><p v-if="state.drillLoading" class="empty">正在读取快照订单…</p><p v-if="state.drillError" class="error">{{state.drillError}} <button :disabled="locked" @click="controller.move(state.selection.page||1)">重试本页</button></p><template v-if="state.drill"><div class="table-scroll"><table><thead><tr><th>医院 / 采购单</th><th>接收 / 实际确认日</th><th>需求 kg</th><th>确认 / 缺货 kg</th><th>采用来源</th><th></th></tr></thead><tbody><tr v-for="o in state.drill.items" :key="o.id"><td><strong>{{o.hospitalName}}</strong><small>{{o.orderNo}}</small><small>{{o.demandLines.map(l=>l.name+' '+l.spec).join('、')}}</small></td><td>{{o.receivedDate}}<small>{{o.confirmed?o.confirmedDate||'确认日未知':'待医院确认'}}</small></td><td>{{o.demandQuantity}}</td><td>{{quantityLabel(o.confirmedQuantity,o.coverage,'confirmed')}}<small>缺货 {{quantityLabel(o.missingQuantity,o.coverage,'missing')}}</small></td><td>{{o.entryMode==='historical_backfill'?'历史已核实':'冻结采购'}} R{{o.revisionNo}}<small>修订 {{o.revisionId}}</small><small>{{o.confirmationSourceId?'最终来源 '+o.confirmationSourceId:'待确认'}}</small></td><td><button :disabled="locked" @click="openOrder(o.id)">查看当前档案 ›</button><small>{{o.writable?'订单负责人':'只读旧单'}}</small></td></tr></tbody></table></div><p v-if="!state.drill.items.length" class="empty">{{state.drill.total===0&&selectedPeriod?'期间无符合筛选订单。':'本页没有可核对的订单。'}}</p><div class="pagination"><span>{{state.drill.total}} 单 · 第 {{state.drill.page}} / {{pages}} 页</span><button :disabled="locked||state.drill.page<=1" @click="controller.move(state.drill.page-1)">上一页</button><button :disabled="locked||state.drill.page>=pages" @click="controller.move(state.drill.page+1)">下一页</button></div><p class="caption">{{state.drill.notice}}</p></template></section>
  </template>
 </section>
</template>
<style scoped>
.hospital-analytics{color:#20394a}.heading h2{margin:4px 0 8px;font-size:26px}.eyebrow,.chart>small,.trend-heading small{font-size:11px;letter-spacing:.1em;color:#587586}.muted,.chart p,.drill>p{font-size:13px;color:#647987;line-height:1.6}.filters{display:flex;gap:12px;align-items:end;flex-wrap:wrap;padding:20px 0;border-bottom:1px solid #dce5ea}.filters label{display:flex;flex-direction:column;gap:7px;font-size:12px;color:#536c7d}.filters input,.filters select{box-sizing:border-box;min-height:38px;padding:7px 9px;border:1px solid #cbd8e0;border-radius:5px;max-width:180px;background:white}.hospital-analytics button{font:inherit;font-size:13px;border:1px solid #cfdae2;border-radius:5px;background:white;color:#244e66;padding:9px 12px;cursor:pointer}.hospital-analytics button:disabled{cursor:default;opacity:.5}.hospital-analytics button.primary{background:#285f7b;color:white;border-color:#285f7b;min-height:38px}.notice,.error{padding:12px 14px;background:#f0f5f7;font-size:13px}.error{background:#fff2ee;color:#a43f27}.meta{display:flex;flex-wrap:wrap;gap:8px 22px;padding:20px 0 12px;font-size:12px;color:#627784}.meta strong{color:#2f4a5b}.meta small{flex-basis:100%;font-size:11px;overflow-wrap:anywhere}.summary{display:grid;grid-template-columns:1fr 1.1fr 1.5fr;gap:28px;padding:15px 0 18px}.summary small{display:block;font-size:12px;color:#627784;margin-bottom:9px}.summary strong{font-size:25px;font-weight:600;font-variant-numeric:tabular-nums}.summary em{font-size:14px;font-style:normal;font-weight:400}.summary .result{font-size:22px;color:#317a69}.coverage,.caption{font-size:12px;color:#70818c;line-height:1.7}.legend{display:flex;gap:20px;flex-wrap:wrap;font-size:12px;color:#647987;border-bottom:1px solid #dce5ea;padding:12px 0 20px}.legend span{display:flex;align-items:center;gap:6px}.legend i{width:10px;height:10px;display:inline-block}.demand{background:#3c708c}.confirmed{background:#3b8b79}.missing{background:#be8a62}.charts{display:grid;grid-template-columns:1fr 1fr;gap:0 32px}.chart{padding:24px 0;border-bottom:1px solid #dce5ea;min-width:0}.chart h3,.drill h3{font-size:17px;margin:8px 0}.chart p{margin:0 0 18px}.bars{max-height:360px;overflow:auto;padding-right:7px}.hospital-analytics .chart-row{display:block;width:100%;border:0;border-radius:0;padding:12px 0;text-align:left;background:transparent}.chart-row:hover{background:#f6f9fb}.row-head{display:flex;gap:10px;justify-content:space-between;font-size:12px;line-height:1.5}.row-head strong{font-weight:500}.track{display:flex;height:10px;margin-top:8px;background:#f0f4f6;width:100%;border-radius:2px;overflow:hidden}.track i{display:block;height:100%;transition:width .2s ease}.stacked{height:14px}.chart-row .caption{display:block;margin-top:5px}.empty{display:block;padding:24px 0;color:#7b8b96;font-size:13px}.trend{grid-column:1/-1}.trend-heading{display:flex;justify-content:space-between;align-items:center;gap:20px}.switch{display:flex;gap:8px}.switch .active{background:#e8f0f4;border-color:#6f95aa}.trend-scroll{overflow-x:auto}.trend-scroll svg{display:block;min-width:650px;width:100%;height:260px;overflow:visible}.trend-scroll text{font:11px system-ui;fill:#607988}.trend-scroll g{cursor:pointer;outline-offset:3px}.period-buttons{display:flex;gap:8px;flex-wrap:wrap;max-height:120px;overflow:auto}.period-buttons button{font-size:11px;padding:6px 8px}.drill{padding-top:26px}.table-scroll{overflow:auto}table{width:100%;border-collapse:collapse;min-width:850px;font-size:12px}th,td{text-align:left;padding:13px 12px;border-bottom:1px solid #e0e7ec;vertical-align:top}th{color:#687e8c;font-weight:500;background:#f5f8fa}td small{display:block;margin-top:5px;color:#718593;font-size:11px;overflow-wrap:anywhere;max-width:220px}.pagination{display:flex;align-items:center;justify-content:flex-end;gap:12px;margin-top:18px;font-size:12px}.pagination span{margin-right:auto}@media(max-width:850px){.charts{grid-template-columns:1fr}.summary{grid-template-columns:1fr;gap:18px}.trend-heading{align-items:flex-start;flex-direction:column}.filters input,.filters select{max-width:155px}.summary strong{font-size:22px}}
@media(prefers-reduced-motion:reduce){.track i{transition:none}}
</style>
